import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Navigation tree","description":"","frontmatter":{"title":"Navigation tree","covers":{"screens":["SCR-055"],"stories":["US-054","US-094","US-095","US-096","US-097","US-132","US-133","US-135","US-136"]}},"headers":[],"relativePath":"usage/navigation.md","filePath":"usage/navigation.md"}`),a={name:`usage/navigation.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="navigation-tree" tabindex="-1">Navigation tree <a class="header-anchor" href="#navigation-tree" aria-label="Permalink to “Navigation tree”">​</a></h1><p>The navigation tree arranges catalogs, entities, solutions and diagrams in folders, for example <em>IT Landscape &gt; Application Inventory</em>, so that you find what you need for your task without searching. Everybody with the permission <code>entity:read</code> (for example the role <code>viewer</code>) sees the tree. Changing it needs the permissions <code>viewpoint:manage</code> and <code>entity:read</code> (role <code>enterprise-architect</code>).</p><h2 id="the-sidebar" tabindex="-1">The sidebar <a class="header-anchor" href="#the-sidebar" aria-label="Permalink to “The sidebar”">​</a></h2><p>After login, the sidebar on the left of every page has two tabs: <em>Browser</em> and <em>Navigation tree</em>. <em>Browser</em> is active when you log in; the tab you choose stays active while you move between pages (see <a href="#browser">Browser</a>). <em>Navigation tree</em> shows the tree below. It starts at the folder <em>Repository</em>.</p><ul><li><strong>Open and close a folder:</strong> choose the arrow or the name of the folder. The sidebar remembers which folders are open until you close the browser tab.</li><li><strong>Open an entry:</strong> choose it. A catalog opens with its default view, if it has one (see <a href="./catalogs#views">Views</a>); an entity opens its page, a solution its solution page, a diagram its page.</li><li><strong>Narrow screens:</strong> the sidebar is hidden; the menu button at the left of the header opens it. Choosing an entry closes it again.</li></ul><p>Folders and entries keep the order in which you arrange them (see <a href="#reorganize-the-tree">Reorganize the tree</a>); new folders and entries go to the end. An entry shows its display label if it has one, otherwise the name of the catalog, entity, solution or diagram. An icon shows the kind of entry, and a person icon marks a personal catalog.</p><h2 id="browser" tabindex="-1">Browser <a class="header-anchor" href="#browser" aria-label="Permalink to “Browser”">​</a></h2><p>The tab <em>Browser</em> needs no manual work: it lists what the repository holds, ordered by solution. Everybody with the permission <code>entity:read</code> sees it. It shows, from top to bottom:</p><ol><li><strong>Current state:</strong> the objects of the repository as they are now, in the categories <em>Components</em> (entities that are not connections and not deleted), <em>Connections</em>, <em>Catalogs</em> (the catalogs you see: shared ones and your own personal ones) and <em>Diagrams</em> (all <a href="./diagrams">diagrams</a> that are not deleted).</li><li><strong>Plateaus:</strong> one node for each plateau in the status <em>transition</em> or <em>target</em>, ordered by the date from which it is valid, then by name. The baseline and realized plateaus have no node. Under a plateau you find the solutions that target it, sorted by name.</li><li><strong>Projects:</strong> the solutions without plateaus, sorted by name.</li></ol><p>Only active solutions appear: a solution with the status <em>implemented</em> or <em>archived</em> is not listed. The entities of an implemented solution count under <em>Current state</em>. A plateau or <em>Projects</em> without solutions stays visible, shown as <em>(0)</em>.</p><p>Each solution has the category <em>Components</em>: its changes to the repository, marked <em>New</em>, <em>Modified</em> or <em>Retiring</em>. Every category shows how many objects it holds. An empty category is greyed out, not hidden.</p><ul><li><strong>Expand a node:</strong> choose the arrow or the name. A category loads its objects when you expand it first; it lists them by name, 50 at a time. Choose <em>Load more</em> for the next 50.</li><li><strong>Open an object:</strong> an entity opens its change history, a catalog its page, a diagram its page, and a change of a solution (and the link symbol next to a solution) the solution page.</li><li><strong>Metatype:</strong> a small label next to an entity shows the abbreviation of its metatype, if it has one.</li><li><strong>Notation:</strong> a small label next to a diagram shows the notation of its viewpoint, for example <em>bpmn2</em>. <em>Diagrams</em> lists them by name, regardless of upper and lower case, 50 at a time; a solution has no category <em>Diagrams</em>.</li></ul><p><em>Components</em> of <em>Current state</em> lists the root level: the entities without a parent. An entity with children shows an arrow and expands to them, by name, 50 at a time. See <a href="#arrange-components">Arrange components</a> to place a component under another one. Components of a solution stay a flat list.</p><p>Arrange the folders of the tree in the tab <em>Navigation tree</em>. Functional and solution building blocks follow with their content.</p><h2 id="arrange-components" tabindex="-1">Arrange components <a class="header-anchor" href="#arrange-components" aria-label="Permalink to “Arrange components”">​</a></h2><p>Real architectures are hierarchical: the module <em>Finance module</em> belongs to the system <em>SAP S/4HANA</em>. In <em>Current state &gt; Components</em> you place a component under another one. This changes the entity itself in the catalog, not only the sidebar: it writes a new version of the child with the field <em>Parent</em> in its <a href="./change-history">change history</a>, and it needs the permission <code>entity:write</code> (roles <code>enterprise-architect</code>, <code>solution-architect</code>). Everybody else sees the hierarchy but cannot change it.</p><ul><li><strong>Drag and drop:</strong> drag a component onto another component, or onto <em>Components</em> to place it at the root level. A target that cannot take it (the component itself, one of its children shown in the sidebar) shows <em>Cannot be dropped here</em>, and nothing is sent.</li><li><strong>Without a mouse:</strong> the button <em>…</em> next to a component offers <em>Move to…</em>. The dialog lists the components level by level; use the arrow to see the children of a component, the filter to narrow the loaded names, <em>Root level</em> for the root level, and <em>Move here</em> to choose the target.</li><li><strong>Rules:</strong> the parent is another component that is not deleted. A cycle (a component under its own child) and more than 10 levels are refused with <em>The component cannot be placed there.</em> A component with an open issue of a solution cannot be changed. If someone else changed the component meanwhile, the sidebar says so and reads the list again; try again then.</li></ul><p>If the metamodel marks a <a href="./../administration/metamodel-editing#composition">composition connection type</a>, placing a component under another one also creates a connection of this type from the parent to the child, when the type allows both entity types. Moving or detaching the component deletes the connection created this way; connections you wrote yourself stay. <em>Connections</em> counts one more connection.</p><h3 id="structuring-aids" tabindex="-1">Structuring aids <a class="header-anchor" href="#structuring-aids" aria-label="Permalink to “Structuring aids”">​</a></h3><p>A structuring aid is a folder in the hierarchy without meaning: it groups components for navigation, for example <em>Finance landscape</em>, without adding a connection to the model. It has a folder symbol, no properties and no connections, and it is no part of a solution.</p><ul><li><strong>New structuring aid:</strong> the button next to <em>Components</em> creates one at the root level; the entry <em>New structuring aid</em> of a component creates one below it. Enter a name of 1 to 255 characters and, optionally, a description of up to 2000 characters. This needs <code>entity:write</code>.</li><li><strong>Delete:</strong> the entry <em>Delete</em> of a structuring aid needs <code>entity:write</code> and <code>entity:delete</code> (role <code>enterprise-architect</code>). The dialog first says how many children move to the root level; they are not deleted. A structuring aid with a child that has an open issue cannot be deleted.</li></ul><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to “Folders”">​</a></h2><p>With the permissions to change the tree, the button <em>…</em> next to a folder offers:</p><ul><li><strong>New folder:</strong> creates a folder inside it. Enter a name and choose <em>Create</em>.</li><li><strong>Rename:</strong> changes the name of the folder, the folder <em>Repository</em> included. Its entries and subfolders stay.</li><li><strong>Move up</strong>, <strong>Move down</strong> and <strong>Move to…:</strong> see <a href="#reorganize-the-tree">Reorganize the tree</a>.</li><li><strong>Delete:</strong> asks first and names how many subfolders and entries the deletion removes. The folder is deleted with all its subfolders and entries. <strong>No catalog, entity or solution is deleted</strong>; they stay available and in other folders. The folder <em>Repository</em> cannot be deleted.</li></ul><p>A folder name has 1 to 255 characters and is unique within its folder, regardless of upper and lower case; otherwise the dialog says <em>A folder with this name already exists</em>. The tree has at most 10 levels below <em>Repository</em> and at most 500 folders.</p><h2 id="place-a-diagram" tabindex="-1">Place a catalog, an entity, a solution or a diagram <a class="header-anchor" href="#place-a-diagram" aria-label="Permalink to “Place a catalog, an entity, a solution or a diagram”">​</a></h2><ol><li>Choose <em>Place in navigation</em>: <ul><li>for a catalog, on the page of the catalog;</li><li>for an entity, in its row of a catalog (not offered in catalogs of connections);</li><li>for a solution, in the header of the solution page;</li><li>for a diagram, in the header of the page of the diagram.</li></ul></li><li>Under <em>Folder</em>, choose the folder by its path, for example <em>Repository / IT Landscape</em>.</li><li>Optionally, enter a <em>Display label</em>. The tree then shows it instead of the name, for example <em>System Inventory</em> for <em>Application Inventory</em>. The catalog, entity or solution keeps its name.</li><li>Choose <em>Place</em>.</li></ol><p>Each of them can be placed in several folders, but only once per folder. A folder has at most 200 entries. If the folder already holds it or is full, the dialog says so, for example <em>The catalog is already in this folder, or the folder is full</em>. A diagram that has been deleted cannot be placed; its entries in the tree are hidden until the diagram is <a href="./diagrams#restore-a-diagram">restored</a>.</p><h2 id="reorganize-the-tree" tabindex="-1">Reorganize the tree <a class="header-anchor" href="#reorganize-the-tree" aria-label="Permalink to “Reorganize the tree”">​</a></h2><p>With the permissions to change the tree, you arrange folders and entries in the sidebar:</p><ul><li><strong>Drag and drop:</strong> drag a folder or an entry to another place in the same folder or into another folder. Where it cannot go, the sidebar shows <em>Cannot be dropped here</em>, for example a folder dropped into its own subfolder.</li><li><strong>Without a mouse:</strong> the button <em>…</em> next to a folder or an entry offers <em>Move up</em>, <em>Move down</em> and <em>Move to…</em>. <em>Move to…</em> asks for the target folder and moves it to the end there.</li></ul><p>A move keeps the rules of the tree: at most 10 levels, at most 200 entries per folder, unique folder names, and an entry only once per folder. Reordering within a full folder is possible. Otherwise the sidebar says <em>It cannot be moved there. The tree may have changed meanwhile.</em> If a folder or entry no longer exists because someone else changed the tree meanwhile, the sidebar reads the current tree again.</p><h2 id="remove-an-entry-from-the-tree" tabindex="-1">Remove an entry from the tree <a class="header-anchor" href="#remove-an-entry-from-the-tree" aria-label="Permalink to “Remove an entry from the tree”">​</a></h2><p>The button <em>×</em> next to an entry removes it from that folder. Only this entry is removed: the catalog, entity or solution itself and its entries in other folders stay.</p><h2 id="deleted-entities" tabindex="-1">Deleted entities <a class="header-anchor" href="#deleted-entities" aria-label="Permalink to “Deleted entities”">​</a></h2><p>When an entity is deleted, its entries stay in the tree and show the marker <em>Deleted</em>. Remove them with <em>×</em>, or restore the entity; the marker then disappears.</p><h2 id="personal-catalogs" tabindex="-1">Personal catalogs <a class="header-anchor" href="#personal-catalogs" aria-label="Permalink to “Personal catalogs”">​</a></h2><p>You can place your own personal catalog like a shared one. Only you see its entry: the tree never shows other people&#39;s personal catalogs, so it never leads to a catalog you cannot open. If you later share the catalog, everybody sees the entry.</p><p>Every change of the tree, moves included, is recorded in the audit trail.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><ul><li><code>GET /views/browser</code> returns the top level of the browser: <code>currentState</code> with the counts <code>components</code>, <code>connections</code>, <code>catalogs</code> and <code>diagrams</code>, <code>plateaus</code> (each with its <code>solutions</code>) and <code>projects</code>; a solution has <code>id</code>, <code>name</code>, <code>status</code> and the number of its changes in <code>components</code>.</li><li><code>GET /views/browser/items</code> returns one page of a category, ordered by name: <code>scope</code> (<code>current-state</code> or <code>solution</code>), <code>category</code> (<code>components</code>, <code>connections</code>, <code>catalogs</code> or <code>diagrams</code>; a solution has <code>components</code> only; an item of a diagram has the <code>notation</code> of its viewpoint), <code>solutionId</code> for a solution, and <code>page</code> and <code>pageSize</code> (1 to 200, default 50). A <code>pageSize</code> outside 1 to 200 is rejected with 400; a category that the scope does not have, or a <code>solutionId</code> that does not match the scope, with 422 naming <code>category</code> or <code>solutionId</code>; an unknown solution with 404.</li><li><code>GET /views/explorer</code> returns the tree from the root as you see it, in its manual order: each folder with <code>id</code>, <code>name</code>, <code>parentId</code>, <code>sortOrder</code>, <code>items</code> and <code>children</code>; each entry with <code>itemType</code> (<code>catalog</code>, <code>entity</code>, <code>solution</code> or <code>diagram</code>), <code>referenceId</code> (catalog, solution or diagram ID) or <code>entityId</code>, <code>displayLabel</code>, <code>name</code>, <code>scope</code> and <code>deleted</code>.</li><li><code>POST /tree-nodes</code> with <code>name</code> and <code>parentId</code> creates a folder; <code>PATCH /tree-nodes/{nodeId}</code> with <code>name</code> renames it; <code>DELETE /tree-nodes/{nodeId}</code> deletes it.</li><li><code>POST /tree-nodes/{nodeId}/items</code> with <code>itemType</code>, <code>referenceId</code> or <code>entityId</code> and an optional <code>displayLabel</code> places an entry; <code>DELETE /tree-nodes/{nodeId}/items/{itemId}</code> removes it.</li><li><code>PUT /tree-nodes/{nodeId}/position</code> with <code>parentId</code> and <code>position</code> moves a folder; <code>PUT /tree-nodes/{nodeId}/items/{itemId}/position</code> with <code>nodeId</code> and <code>position</code> moves an entry. The position counts the entries you see, from 0.</li></ul><p>Every change answers with the whole tree. Invalid input is rejected with 422 and names the field in <code>invalidFields</code>, for example <code>name</code> for a taken folder name, <code>parentId</code> for a move that would create a cycle or go too deep, or <code>nodeId</code> for a target folder that already holds the entry or is full.</p>`,42)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};